define(["jquery"],function($){function isMobileViewport(){return window.matchMedia("(max-width: 991.98px)").matches}function syncButtons(shell,isOpen){shell.querySelectorAll("[data-kopere_dashboard-sidebar-open]").forEach(function(button){button.setAttribute("aria-expanded",isOpen?"true":"false")})}function closeSidebar(shell){shell.classList.remove("is-sidebar-open");document.body.classList.remove("has-kopere_dashboard-sidebar-open");syncButtons(shell,false)}function openSidebar(shell){shell.classList.add("is-sidebar-open");document.body.classList.add("has-kopere_dashboard-sidebar-open");syncButtons(shell,true)}function bindShell(shell){if(!shell){return}let openButtons=shell.querySelectorAll("[data-kopere_dashboard-sidebar-open]");let closeButtons=shell.querySelectorAll("[data-kopere_dashboard-sidebar-close]");let backdrop=shell.querySelector("[data-kopere_dashboard-sidebar-backdrop]");openButtons.forEach(function(button){button.addEventListener("click",function(){if(shell.classList.contains("is-sidebar-open")){closeSidebar(shell);return}openSidebar(shell)})});closeButtons.forEach(function(button){button.addEventListener("click",function(){closeSidebar(shell)})});if(backdrop){backdrop.addEventListener("click",function(){closeSidebar(shell)})}shell.querySelectorAll(".kopere_dashboard-card-sidenav a").forEach(function(link){link.addEventListener("click",function(){if(isMobileViewport()){closeSidebar(shell)}})});syncButtons(shell,false)}function init(){let shells=Array.prototype.slice.call(document.querySelectorAll("[data-kopere_dashboard-shell]"));if(!shells.length){return}shells.forEach(function(shell){bindShell(shell)});document.addEventListener("keydown",function(event){if(event.key!=="Escape"){return}shells.forEach(function(shell){closeSidebar(shell)})});$(window).on("resize",function(){if(isMobileViewport()){return}shells.forEach(function(shell){closeSidebar(shell)})})}return{init:init}});